// 烷烃沸点数据
const alkaneData = [
  { name: '甲烷', formula: 'CH₄', carbon: 1, bp: -161.5, state: '气态', color: '#3498db' },
  { name: '乙烷', formula: 'C₂H₆', carbon: 2, bp: -88.6, state: '气态', color: '#3498db' },
  { name: '丙烷', formula: 'C₃H₈', carbon: 3, bp: -42.0, state: '气态', color: '#3498db' },
  { name: '丁烷', formula: 'C₄H₁₀', carbon: 4, bp: -0.5, state: '气态', color: '#3498db' },
  { name: '戊烷', formula: 'C₅H₁₂', carbon: 5, bp: 36.1, state: '液态', color: '#f39c12' },
  { name: '己烷', formula: 'C₆H₁₄', carbon: 6, bp: 68.7, state: '液态', color: '#f39c12' },
  { name: '庚烷', formula: 'C₇H₁₆', carbon: 7, bp: 98.4, state: '液态', color: '#f39c12' },
  { name: '辛烷', formula: 'C₈H₁₈', carbon: 8, bp: 125.7, state: '液态', color: '#f39c12' },
  { name: '壬烷', formula: 'C₉H₂₀', carbon: 9, bp: 150.8, state: '液态', color: '#f39c12' },
  { name: '癸烷', formula: 'C₁₀H₂₂', carbon: 10, bp: 174.1, state: '液态', color: '#f39c12' }
];

let maxDisplay = 10;

function normalizeBP(bp) {
  // 将沸点归一化到图表高度范围 (50-280px)
  const minBP = -170;
  const maxBP = 180;
  const minHeight = 50;
  const maxHeight = 260;
  return minHeight + ((bp - minBP) / (maxBP - minBP)) * (maxHeight - minHeight);
}

function renderChart() {
  const container = document.getElementById('boiling-point-chart');
  container.innerHTML = '';

  const displayData = alkaneData.filter(d => d.carbon <= maxDisplay);

  displayData.forEach((data, index) => {
    const bar = document.createElement('div');
    bar.className = 'bar';
    bar.style.height = normalizeBP(data.bp) + 'px';
    bar.style.background = data.color;

    bar.innerHTML = `
      <div class="bar-label">${data.name}</div>
      <div class="bar-value">${data.bp}°C</div>
    `;

    bar.onclick = () => showInfo(data);

    container.appendChild(bar);
  });
}

function showInfo(data) {
  const infoPanel = document.getElementById('selected-info');
  const stateIcon = data.state === '气态' ? '💨' : data.state === '液态' ? '💧' : '🧊';

  infoPanel.innerHTML = `
    <h4>${stateIcon} ${data.name} (${data.formula})</h4>
    <p><strong>碳原子数：</strong>C${data.carbon}</p>
    <p><strong>沸点：</strong>${data.bp}°C</p>
    <p><strong>状态：</strong>${data.state}</p>
    <p><strong>通式验证：</strong>C${data.carbon}H${2*data.carbon+2} ✓</p>
  `;

  // 发送交互结果到系统
  window.HeurisStage.emit('alkane-selected', {
    name: data.name,
    formula: data.formula,
    carbon: data.carbon,
    boilingPoint: data.bp,
    state: data.state,
    knowledgePoint: '烷烃沸点递变规律'
  });
}

// 滑块控制
document.getElementById('range-slider').oninput = function() {
  maxDisplay = parseInt(this.value);
  document.getElementById('range-label').textContent = `C₁ ~ C${maxDisplay}`;
  renderChart();
};

// 初始化
renderChart();

// 默认选中戊烷（第一个液态烷烃）
setTimeout(() => showInfo(alkaneData[4]), 100);

