const questions = [
  { formula: 'C₂H₆', answer: 'alkane', name: '乙烷' },
  { formula: 'C₃H₆', answer: 'alkene', name: '丙烯' },
  { formula: 'C₂H₂', answer: 'alkyne', name: '乙炔' },
  { formula: 'C₄H₁₀', answer: 'alkane', name: '丁烷' },
  { formula: 'C₃H₈', answer: 'alkane', name: '丙烷' },
  { formula: 'C₂H₄', answer: 'alkene', name: '乙烯' },
  { formula: 'C₅H₁₂', answer: 'alkane', name: '戊烷' },
  { formula: 'C₆H₆', answer: 'benzene', name: '苯' }
];

let currentIndex = 0;
let score = 0;
let totalAnswered = 0;

function loadQuestion() {
  const q = questions[currentIndex];
  document.getElementById('formula-display').textContent = q.formula + ' (' + q.name + ')';
  document.getElementById('feedback-area').innerHTML = '';

  document.querySelectorAll('.option-btn').forEach(btn => {
    btn.classList.remove('correct', 'wrong');
    btn.disabled = false;
  });
}

function checkAnswer(selected) {
  const q = questions[currentIndex];
  const isCorrect = selected === q.answer;
  const btns = document.querySelectorAll('.option-btn');

  totalAnswered++;

  if (isCorrect) {
    score++;
    document.getElementById('feedback-area').innerHTML = '<p style="color:#27ae60;font-size:20px;">✅ 正确！' + q.name + '是' + getAnswerName(q.answer) + '</p>';
    window.HeurisStage.emit('answer', { 
      formula: q.formula, 
      correct: true, 
      score: score,
      total: totalAnswered
    });
  } else {
    document.getElementById('feedback-area').innerHTML = '<p style="color:#e74c3c;font-size:18px;">❌ 不对哦！' + q.name + '应该是<span style="font-weight:bold">' + getAnswerName(q.answer) + '</span></p>';
    window.HeurisStage.emit('answer', { 
      formula: q.formula, 
      correct: false, 
      correctAnswer: q.answer,
      score: score,
      total: totalAnswered
    });
  }

  // 显示所有按钮状态
  btns.forEach(btn => {
    btn.disabled = true;
    if (btn.dataset.answer === q.answer) {
      btn.classList.add('correct');
    } else if (btn.dataset.answer === selected && !isCorrect) {
      btn.classList.add('wrong');
    }
  });

  // 更新分数
  document.getElementById('score-display').textContent = '得分：' + score + ' / ' + totalAnswered;

  // 下一题
  currentIndex = (currentIndex + 1) % questions.length;
  setTimeout(loadQuestion, 2000);
}

function getAnswerName(answer) {
  const names = {
    'alkane': '烷烃',
    'alkene': '烯烃',
    'alkyne': '炔烃',
    'benzene': '芳香烃'
  };
  return names[answer];
}

// 绑定按钮事件
document.querySelectorAll('.option-btn').forEach(btn => {
  btn.addEventListener('click', () => checkAnswer(btn.dataset.answer));
});

// 初始化
loadQuestion();

